  'Source checks use HTTP GET. Unchanged automatic runs skip the agent. An optional JSON pointer watches only that value and ignores object key order. Manual tests always run. Quiet hours defer successful Bot reports. Failures and approvals stay visible. Usage limits can overrun when reports arrive late.':
    'Проверки источника используют HTTP GET. При неизменившихся данных автоматические запуски пропускают агента. Необязательный JSON-указатель отслеживает только указанное значение и не учитывает порядок ключей объекта. Ручные проверки запускаются всегда. В тихие часы успешные отчёты Bot откладываются. Ошибки и запросы на подтверждение остаются видимыми. Лимиты использования могут быть превышены, если отчёты приходят с задержкой.',
