  'Battery & background activity': 'Батарея и работа в фоне',
  'The open computer updates live. Less frequent checks of other computers reduce network activity. Connections pause while the app is in the background; notifications and Live Activities are managed in Notifications. Disabled widgets keep their last saved snapshot.':
    'Подключённый компьютер обновляется в реальном времени. Менее частые проверки других компьютеров сокращают сетевую активность. Подключения приостанавливаются, когда приложение работает в фоне; уведомления и Live Activities настраиваются в разделе «Уведомления». Отключённые виджеты показывают последний сохранённый снимок.',
