    'Введите от 1 до 12 периодов через запятую в порядке меню: m — минуты, h — часы, d — дни, w — недели. Для уже отложенных тредов время пробуждения не изменится.',
  Confirmations: 'Подтверждения',
  'Archived threads can always be restored from Settings → Archived threads. Stopping pauses queued messages.':
    'Архивированные треды всегда можно восстановить в разделе «Настройки» → «Архивированные треды». Остановка приостанавливает отправку сообщений из очереди.',
  'Confirm before archiving a task': 'Подтверждать архивацию задачи',
