  'Forget computer': 'Забыть компьютер',
  'Forget {value0}?': 'Забыть {value0}?',
  'This phone’s access is removed from the computer too. Connecting again needs a new pairing code. Work on the computer continues.':
    'Доступ этого телефона также будет удалён с компьютера. Для повторного подключения потребуется новый код сопряжения. Работа на компьютере продолжится.',
  Forget: 'Забыть',
