  'Loading device hosts…': 'Загрузка хостов устройств…',
  'Retry device host settings': 'Повторить загрузку настроек хоста устройств',
  'Device Hub': 'Device Hub',
  'Enable device discovery and controls on this runtime. Turning it off keeps saved hosts and leaves devices running.':
    'Включите обнаружение устройств и управление ими в этой среде выполнения. При отключении сохранённые хосты останутся, а устройства продолжат работать.',
  'Enable Device Hub': 'Включить Device Hub',
  'Remote device hosts': 'Хосты удалённых устройств',
  'The destination requires an updated installed Dovo runtime and an existing pairing. SSH alone does not grant Dovo access.':
    'На целевом компьютере должна быть установлена обновлённая среда выполнения Dovo и настроено сопряжение. Одного SSH недостаточно для доступа Dovo.',
  'No remote device hosts yet. Local devices remain available.':
    'Пока нет хостов удалённых устройств. Локальные устройства по-прежнему доступны.',
  'Add device host': 'Добавить хост устройства',
