  'Local runtime (no remote default)': 'Локальная среда выполнения (удалённый хост не выбран)',
  'Preselects this host in the desktop device picker. The mobile picker shows devices from all reachable hosts.':
    'Этот хост будет предварительно выбран в средстве выбора устройств для компьютера. В мобильном средстве выбора показываются устройства со всех доступных хостов.',
  'Remove device host': 'Удалить хост устройства',
