    'Этот путь к ключу относится к компьютеру с текущей средой выполнения, а не к этому телефону или целевому компьютеру. Оставьте поле пустым, чтобы использовать настройки SSH по умолчанию для среды выполнения. Поддерживается только аутентификация по ключу; никогда не вставляйте и не загружайте закрытый ключ.',
