  'Cancel move': 'Отменить перенос',
  'Cancel copy': 'Отменить копирование',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Перенесите всю сохранённую переписку, список задач, вложения и файлы. Сеансы провайдера и учётные данные останутся здесь. В треде на целевом компьютере будет использоваться настроенный там harness с уровнем доступа не выше, чем у этого треда. Ничего не запустится, пока вы не отправите там следующее сообщение. После открытия можно сменить модель. Для восстановления этот тред останется здесь доступным только для чтения.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Скопируйте файлы и локальную историю Git. Исходный проект и чаты останутся здесь. На целевом компьютере будет создана новая папка. Для рабочих деревьев используется настроенная там папка рабочих деревьев.',
