  'At this level: {value0}': 'На этом уровне: {value0}',
  'Project overrides Computer; Project on computer wins over both. The check marks the effective value for each computer, including later overrides.':
    'Проект переопределяет компьютер; проект на компьютере имеет приоритет над обоими. Галочка отмечает действующее значение для каждого компьютера, включая последующие переопределения.',
  'The value above comes from the latest settings read. Source details below use saved snapshots.':
    'Указанное выше значение взято из последних прочитанных настроек. Сведения об источниках ниже основаны на сохранённых снимках.',
