  ' · current draft': ' · текущий черновик',
  'These levels keep their own value when {value0} changes. Open one to edit it, or reset them all to inherit again.':
    'Эти уровни сохраняют собственные значения при изменении «{value0}». Откройте уровень, чтобы изменить его, или сбросьте все значения, чтобы снова наследовать их.',
  'Open {value0} settings for {value1}': 'Открыть настройки {value0} для {value1}',
  'Resetting…': 'Сброс…',
  'Reset all later {value0} overrides': 'Сбросить все последующие переопределения {value0}',
  'Use inherited {value0}{value1}': 'Использовать унаследованное значение {value0}{value1}',
  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Настройте CuaDriver на хосте среды выполнения. CuaDriver управляет разрешениями ОС; Dovo подключает агентов через MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Имена исполняемых файлов хоста или пути к ним без кавычек оболочки. Переопределения агента имеют приоритет. Новые терминалы используют эти настройки оболочки.',
  'Loading {value0} settings…': 'Загрузка настроек {value0}…',
  'computer-use': 'computer-use',
  command: 'command',
  'Shell arguments (one per line)': 'Аргументы оболочки (по одному в строке)',
  'Automatic shell: {value0}. Default: -l (login shell).':
    'Автоматическая оболочка: {value0}. По умолчанию: -l (оболочка входа).',
  'Enable agent computer use on this computer':
    'Разрешить агенту управлять компьютером на этом компьютере',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Предоставляет агентам с доступом на запись доступ к рабочему столу этого компьютера. Агентам с доступом только для чтения доступ не предоставляется. Пользователь и агенты используют общий рабочий стол и состояние приложений.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Оставьте поле Cua Driver пустым, чтобы найти его в PATH этого компьютера или стандартной папке установки. Изменения применяются при следующих действиях агента.',
  '1. Install on this computer': '1. Установите на этот компьютер',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Запустите официальный установщик на хосте среды выполнения, затем обновите статус. Он загрузит и установит CuaDriver; учётная запись Cua не нужна.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Для минимальных систем Linux требуются libxi6 и at-spi2-core. Для GNOME необходима встроенная в Cua вспомогательная программа WinRects; см. руководство по установке.',
  'Install and set up Cua Driver': 'Установить и настроить Cua Driver',
  'Detect / check Cua Driver': 'Обнаружить / проверить Cua Driver',
  '2. Permissions & desktop access': '2. Разрешения и доступ к рабочему столу',
  '3. Agent MCP, skills & hooks': '3. MCP, навыки и хуки агента',
  '4. Computer History (optional preview)':
    '4. Computer History (необязательная предварительная версия)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Предоставьте CuaDriver разрешения «Универсальный доступ» и «Запись экрана» в macOS и согласитесь на перезапуск. Проверка доступа к рабочему столу выводит список приложений, не изменяя их. Управление службой влияет на активные сеансы управления компьютером.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Сохраните переключатель управления компьютером, чтобы автоматически подключать dovo_cua MCP в новых сеансах агентов с доступом на запись. Регистрировать MCP вручную не нужно. Установите необязательный официальный пакет навыков; при установке он подключит обнаруженные агенты на этом компьютере.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'История по желанию: шифруется, содержит только метаданные. Включение может перезапустить службу. При выключении записанные данные сохраняются; приостановка временно прекращает запись. В неподдерживаемых сборках отображается ошибка. Данные остаются на хосте среды выполнения; команда «Просмотреть недавнюю историю» загружает сюда до 20 событий.',
  'Delete recorded Computer History?': 'Удалить записанную историю Computer History?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Удалить всю записанную историю и её ключ шифрования на этом компьютере? Это действие нельзя отменить.',
