  'Last connected {value0}': 'Последнее подключение: {value0}',
  'Open pull requests': 'Открытые запросы на слияние',
  '{value0} PRs need action · {value1} open{value2}':
    'Требуют действий: {value0} PR · открыто: {value1}{value2}',
  'PR summary could not refresh': 'Не удалось обновить сводку PR',
  'Partial results · open PRs to load more':
    'Показаны не все результаты · откройте PR, чтобы загрузить остальные',
  'View tasks on this device': 'Просмотреть задачи на этом устройстве',
  'This computer connection changed. Choose where to create this work again.':
    'Подключение к этому компьютеру изменилось. Выберите, где создать эту работу заново.',
  'Choose another computer': 'Выбрать другой компьютер',
  'Choose where this work should run.': 'Выберите, где должна выполняться эта работа.',
  'Shows connection details': 'Показывает сведения о подключении',
  'Reconnects. Touch and hold for details':
    'Переподключается. Нажмите и удерживайте, чтобы посмотреть подробности',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Этот телефон больше не сопряжён с компьютером ниже. Он был удалён на том компьютере или среда выполнения была сброшена. Выполните сопряжение снова в разделе «Устройства» в настройках.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Подключение использует обновления HTTP. Потоковая передача в реальном времени переподключается или недоступна. Переподключитесь, чтобы повторить попытку.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Сохранённая работа остаётся доступной. Переподключите компьютер, чтобы отправлять сообщения или выполнять на нём команды.',
  '{value0} · {value1} saved actions': '{value0} · сохранённых действий: {value1}',
  'Thread: {value0}': 'Ветка: {value0}',
  'Computer access changed. This action may already have run.':
    'Доступ к компьютеру изменился. Возможно, это действие уже выполнено.',
  'Retry action': 'Повторить действие',
  'Retry this action?': 'Повторить это действие?',
  'Computer access changed. This action may already have run; retrying could repeat it. Check the computer before continuing.':
    'Доступ к компьютеру изменился. Возможно, это действие уже выполнено; повтор может выполнить его ещё раз. Перед продолжением проверьте компьютер.',
  'Discard action': 'Отменить действие',
  'Discard this action?': 'Отменить это действие?',
  'Unsent work will be removed from this phone. Actions already applied on the computer remain applied.':
    'Неотправленная работа будет удалена с этого телефона. Действия, уже выполненные на компьютере, останутся в силе.',
  'Retry saved actions': 'Повторить сохранённые действия',
  'Retry saved actions on {value0}?': 'Повторить сохранённые действия на {value0}?',
  'Access to this computer was renewed. Some saved actions may already have run and retrying could repeat them. Check the computer before continuing. Messages keep their original delivery identity.':
    'Доступ к этому компьютеру восстановлен. Некоторые сохранённые действия могли уже выполниться; повтор может выполнить их ещё раз. Перед продолжением проверьте компьютер. Исходные данные отправителя сообщений сохраняются.',
  'Discard saved actions': 'Удалить сохранённые действия',
  'Discard saved actions?': 'Удалить сохранённые действия?',
  'Actions already applied on the computer will remain applied. Unsent actions will be removed from this phone.':
    'Действия, уже выполненные на компьютере, останутся в силе. Неотправленные действия будут удалены с этого телефона.',
  'Saved attachment': 'Сохранённое вложение',
  'Attach to the task’s current draft or discard the upload. Existing files remain unchanged.':
    'Добавьте файл в текущий черновик задачи или отмените загрузку. Существующие файлы не изменятся.',
