  'Discard saved upload?': 'Отменить сохранённую загрузку?',
  'This permanently abandons this upload. An attachment already saved in a message or draft is not removed.':
    'Загрузка будет окончательно отменена. Вложение, уже сохранённое в сообщении или черновике, не будет удалено.',
  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Выполнить сопряжение снова',
  'Connection stages': 'Этапы подключения',
  'Start your computer': 'Запустите компьютер',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Откройте Dovo на компьютере и не переводите его в режим сна. В разделе «Настройки» → «Устройства и среда выполнения» войдите в систему и включите Dovo Connect. Войдите в ту же учётную запись на телефоне и выберите Connect. Для доступа через интернет не нужны код сопряжения, VPN или локальный IP-адрес.',
  'Direct internet connection': 'Прямое подключение через интернет',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN устанавливает прямое подключение между телефоном и компьютером. Ваши данные защищены сквозным шифрованием. Включение Dovo Connect разрешает использовать зашифрованный ретранслятор, если сеть блокирует прямые подключения. Ретранслятор передаёт зашифрованный трафик и не может прочитать ваши данные.',
  'LAN / VPN connections': 'Подключения по LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Выполните отдельное сопряжение по LAN / VPN, чтобы предпочитать это подключение, когда оно доступно. Скопируйте полный адрес Wi-Fi, Tailscale, NetBird или HTTPS, показанный на компьютере, включая порт. localhost и 0.0.0.0 — это адреса, к которым телефон не сможет подключиться.',
  'Check your network': 'Проверьте сеть',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Используйте одну сеть Wi-Fi или подключите оба устройства к VPN. Для подключения по Wi-Fi разрешите Dovo доступ к локальной сети в настройках iPhone.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Срок действия кодов сопряжения — две минуты. Коды CLI подтверждаются автоматически; код из настольного приложения может потребовать подтверждения на компьютере.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Сопряжение сохранено. Перед созданием нового кода попробуйте переподключиться. Если адрес изменился, выберите «Обновить адрес подключения» в настройках этого компьютера.',
