  'Memory limit (MB)': 'Лимит памяти (МБ)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Запускает агента каждой новой беседы, его команды и терминалы в локальном контейнере Docker или Podman. Монтируются только рабочая копия и данные входа выбранного агента. Текущие беседы сохраняют свою настройку.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Без доступа к сети агент не может обратиться к API своей модели, если только этот API не работает внутри песочницы. Установка пакетов и веб-запросы тоже не выполняются.',
  preparing: 'подготовка',
  stopped: 'остановлена',
  'A thread can change it before its first message.':
    'Беседа может изменить это до своего первого сообщения.',
  'Full network access. The agent can reach any address the host can.':
    'Полный доступ к сети. Агент может обратиться к любому адресу, доступному хосту.',
  'Leave empty for no limit.': 'Оставьте пустым, чтобы не задавать лимит.',
  'Leave empty for the default of {value0} MB.':
    'Оставьте пустым для значения по умолчанию {value0} МБ.',
  'This thread runs in a Mise container sandbox.':
    'Эта беседа работает в контейнерной песочнице Mise.',
  'The agent runs on this computer with your user account.':
    'Агент работает на этом компьютере под вашей учётной записью.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Агент, его команды и терминалы работают в контейнере. Монтируются только эта рабочая копия и данные входа агента.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Откладывает новую работу, которая выполняется без вашего сообщения, когда её оценочная стоимость достигает лимита. Это касается продолжений ботов, шагов регулярных задач бота, запланированных сообщений и дочерних агентов. Каждая ветка или бот учитывается вместе со своими дочерними агентами. Регулярная задача без бота начинает новый счёт при каждом запуске. Задайте её собственные лимиты в разделе «Мониторинг и лимиты». Ваше следующее сообщение или «Продолжить» сбрасывает счёт. Ходы без цены тоже откладывают работу. Выполняющийся ход всегда завершается.',
